CREATE TABLE IF NOT EXISTS legal_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_type text NOT NULL, title text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', entity_scope text NOT NULL DEFAULT 'Parent Company', version_label text NOT NULL DEFAULT '1.0', status text NOT NULL DEFAULT 'Draft', effective_date date, approval_date date, custodian text, confidentiality text NOT NULL DEFAULT 'Internal', description text, document_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legal_record_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES legal_records(id) ON DELETE CASCADE, version_label text NOT NULL, change_summary text NOT NULL, approved_by text, approval_date date, supersedes_version text, document_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legal_record_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES legal_records(id) ON DELETE CASCADE, approval_stage text NOT NULL, approver_name text, decision text NOT NULL DEFAULT 'Pending', decision_date date, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS regulatory_filings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), regulator text NOT NULL, jurisdiction text NOT NULL, filing_type text NOT NULL, entity_scope text NOT NULL, reference_number text, filing_date date, due_date date, status text NOT NULL DEFAULT 'Pending', responsible_officer text, document_url text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS corporate_record_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid REFERENCES legal_records(id) ON DELETE SET NULL, event_type text NOT NULL, actor_name text, event_note text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
